from hermes_tools import terminal
r=terminal("python3 - <<'PY'
coords=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
# one-indexed inferred 20x20, input rect rows2-8 cols9-15. Lines rows with markers above rectangle? rows2-4,7-8; cols from markers below (9,13,15)
rect={(r,c) for r in range(2,9) for c in range(0,16)}
hr={r for r,c in coords if r<=8}
vc={c for r,c in coords if r>8}
out=rect|{(r,c) for r in hr for c in range(20)}|{(r,c) for r in range(20) for c in vc}
print('horizontal rows',sorted(hr),'vertical cols',sorted(vc),'output cell count',len(out))
print('grid:')
for r in range(20): print(''.join('2' if (r,c) in out else '.' for c in range(20)))
print('non-rect additions:')
print(sorted(out-rect))
PY")
print(r['output'])

